    h, w = len(g), len(g[0])
    key_row = max(r for r in range(h) if len(set(g[r])) > 1 and sum(v != g[0][0] for v in g[r]) < w // 2)
    bg = g[0][0]
    key = [v for v in g[key_row] if v != bg]

    # The markers are the isolated non-background, non-fill cells.
    markers = []
    for r in range(key_row):
        for c in range(w):
            if g[r][c] not in (bg, 2, 1):
                markers.append([g[r][c], r, c])

    def box_at(r, c):
        fill = 2 if bg == 1 else 1
        top = r
        while top > 0 and any(g[top - 1][x] != bg for x in range(max(0, c - 3), min(w, c + 4))):
            top -= 1
        bottom = r
        while bottom + 1 < key_row and any(g[bottom + 1][x] != bg for x in range(max(0, c - 3), min(w, c + 4))):
            bottom += 1
        left = c
        while left > 0 and g[r][left - 1] != bg:
            left -= 1
        right = c
        while right + 1 < w and g[r][right + 1] != bg:
            right += 1
        return top, bottom, left, right

    boxes = []
    for color, r, c in markers:
        top, bottom, left, right = box_at(r, c)
        boxes.append({'color': color, 'r': r, 'c': c, 'top': top,
                      'bottom': bottom, 'left': left, 'right': right})

    def aligned(a, b):
        return a['r'] == b['r'] or a['c'] == b['c']

    def find_path(i, previous, used):
        if i == len(key):
            return []
        for j, b in enumerate(boxes):
            if j not in used and b['color'] == key[i] and (previous is None or aligned(previous, b)):
                tail = find_path(i + 1, b, used | {j})
                if tail is not None:
                    return [b] + tail
        return None

    path = find_path(0, None, frozenset())
    for a, b in zip(path, path[1:]):
        if a['r'] == b['r']:
            lo, hi = sorted((a['c'], b['c']))
